/*
 * A243845  Numbers generated by recursive procedure a(n) = nozero(a(n-1) *
 *          3), in which the function nozero(x) removes all zeros from x,
 *          starting with a(1) = 1.
 * https://oeis.org/A243845
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = nozero(a(n-1) * 3), a(1) = 1
 * Range:     u8 n <= 6, u16 n <= 13, u32 n <= 64, u64 n <= 108, u128 n <= 108,
 *            big any n
 * Validated: standard, pass, 55 terms through n = 98 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* nozero removes all decimal zero digits from its argument. */

#include <stdlib.h>
#include <stdint.h>

/* Remove all zeros from the decimal representation of x and return the result. */
static seq_t nozero(seq_t x)
{
    /* Enough to hold all possible digits up to n ≈ 10000. */
    uint8_t digits[12000];
    size_t len = 0;

    while (x != (seq_t)0) {
        seq_t d = x % (seq_t)10;
        x /= (seq_t)10;
        if (d != (seq_t)0) {
            digits[len++] = (uint8_t)d;
        }
    }

    if (len == 0)
        return (seq_t)0;

    seq_t result = (seq_t)0;
    /* Reconstruct the number from most significant non‑zero digit. */
    while (len--) {
        result = result * (seq_t)10 + (seq_t)digits[len];
    }
    return result;
}

seq_t a(idx_t n)
{
    if (n == (idx_t)1)
        return (seq_t)1;

    seq_t val = (seq_t)1;
    for (idx_t i = (idx_t)2; i <= n; ++i) {
        val = val * (seq_t)3;
        val = nozero(val);
    }
    return val;
}
